1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	export const runScenario = (scenario: Scenario): { results: Result[] } => {
30	  return { results: scenario.steps.map(() => ({ premium: 5 })) };
31	};
32

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Simplest case
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	
15	  // Base premiums per item type (with first insurance surcharge + fee)
16	  it.todo("a single sword → base premium 100 G");
17	  it.todo("a single amulet → base premium 60 G");
18	  it.todo("a single staff → base premium 80 G");
19	  it.todo("a single potion → base premium 40 G");
20	  it.todo("a single rune (component) → base premium 25 G");
21	  it.todo("a single moonstone (component) → base premium 25 G");
22	
23	  // Building block of 3 alike components
24	  it.todo("2 runes → 50 G base premium");
25	  it.todo("3 runes → 60 G base premium (block applies)");
26	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
27	  it.todo("7 runes → 175 G base premium");
28	
29	  // "Alike" components means exactly the same type
30	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
31	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
32	
33	  // Item-specific modifiers
34	  it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
35	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
36	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
37	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");
38	
39	  // Policy-wide modifiers
40	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
41	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
42	  it.todo("first quote in a scenario → 10 % first insurance surcharge on the policy base");
43	  it.todo("second quote in a scenario → 15 % follow-up contract discount");
44	  it.todo("first insurance surcharge still applies on a follow-up contract");
45	
46	  // Modifier scope on multi-item policies
47	  it.todo(
48	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of the cursed item only) → 210 G before further modifiers and fee",
49	  );
50	
51	  // Rounding
52	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
53	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
54	
55	  // Integration examples
56	  it.todo(
57	    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
58	  );
59	  it.todo(
60	    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
61	  );
62	});
63	
64	describe("MHPCO Claim Office — claim", () => {
65	  // Standard reimbursement
66	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
67	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
68	
69	  // Special clauses
70	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
71	  it.todo(
72	    "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)",
73	  );
74	  it.todo(
75	    "dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (50 % rule applies, then deductible)",
76	  );
77	  it.todo(
78	    "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)",
79	  );
80	
81	  // Deductible per damage event
82	  it.todo(
83	    "one incident damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)",
84	  );
85	
86	  // Insurance sum and cap
87	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
88	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
89	  it.todo(
90	    "a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)",
91	  );
92	  it.todo("a cursed sword → cap 2000 G (based on the unmodified insurance value)");
93	
94	  // Cap exhaustion across successive claims
95	  it.todo(
96	    "sword policy (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G with remaining cap 600 G",
97	  );
98	  it.todo("second of the two successive 1500 G claims → payout 600 G, remaining cap 0 G");
99	
100	  // Multiple items of the same type
101	  it.todo(
102	    "two insured swords, two sword damage entries → each entry is a separate damage with its own deductible",
103	  );
104	
105	  // Rounding
106	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
107	});
108	
109	describe("MHPCO Claim Office — errors", () => {
110	  it.todo("quote with an unknown item type (e.g. broomstick) → error");
111	  it.todo("claim damaging an item that is not part of the policy (amulet when only a sword is insured) → error");
112	  it.todo("claim damaging an item of unknown type → error");
113	  it.todo("claim with more damage entries of a type than the policy covers → error");
114	  it.todo("claim with a damage entry of amount -200 → error");
115	});
116	
117	describe("MHPCO Claim Office — CLI", () => {
118	  it.todo("reads a scenario from stdin and writes { results } to stdout in step order");
119	  it.todo("schema example: amulet quote then a 200 G amulet claim → premium and payout/remainingCap");
120	  it.todo("exits with a non-zero status code and writes to stderr on an invalid scenario, with no results on stdout");
121	});
